import numpy as np
def aea(data, confidence):
    std_dev = np.std(data, ddof=1)
    sample_size = len(data)
    margin_of_error = 1.96 * (std_dev / np.sqrt(sample_size))
    lower_bound = aea - margin_of_error
    upper_bound = aea + margin_of_error
    return aea, lower_bound, upper_bound
