    if -10 <= temperature <= 50:
        return temperature
    elif temperature > 50:
        # Assuming the temperature is in Celsius, and some few degree errors are acceptable.
        return 50
    elif temperature < -10:
        # Assuming the temperature is in Celsius, and some few degree errors are acceptable.
        return -10

# Final function getting an OCR output & getting valid temperature
