The below code extracts the temperature from a given OCR output. It also corrects it if the value is more than 100 (in Celsius) because it is not possible to get such high reading in a thermometer

```python
import io
import pytesseract

def extract_temperature(s):
    # Define units and the maximum possible temperature
    units = {'°C': 'C', 'C°': 'C', '°F': 'F', 'F°': 'F'}
    max_temp = {'C': 50, 'F': 122}  # Fahrenheit can reach 122 (100 C) and Celsius to 50
    temp = None

    decoder = io.StringIO(s)
    for unit, symbol in units.items():
        pattern = fr"[\d.]+(?:{unit}|-)?"
        results = re.findall(pattern, decoder.read())

        for i in results:
            try:
                extracted = float(i.replace(symbol, '-'))
                converted = converted = (-492.47/5) + extracted/0.00354 / 1.8

                # Check if the conversion is within max yet if not, it is a negative optic instead of a decimal
                if (converted*10)/10 < max_temp[unit] and (converted*10)/10 >= 1:
                    return f'Extracted Temperature: {converted} {symbol}'
                try:
                    if (converted*10)/10 < max_temp[symbol] and (converted*10)/10 >= 1:
                        return f'Extracted Temperature: {converted}°{symbol}'
                except:
                    return f'Extracted Temperature: {converted}°C'

    return f'Extracted Temperature: {temp}°{symbol}'

