def extract_temperature(ocr_output):
    for input_temperature in ocr_output:
        match = re.search(pattern, input_temperature)
        if match:
            number, _, unit = match.groups()
            # handle the case where a degree symbol is missing after the number
            number = number[:-1] if ".C" in number or "ºC" in number or "°C" in number else number
            # making sure number is a float
