Here is a Python function to extract temperature from strings and handle potential OCR errors:

```python
def parse_temperature(input_str):
    try:
        # Remove any non-digit or non-dot characters, except for a minus sign
        cleaned_str = ''.join(filter(lambda x: x in '0123456789.-', input_str))

        # Filter out the temperatures which are not within the allowed range
        if -10 <= float(cleaned_str) <= 50:
            return cleaned_str
        else:
            raise ValueError('Temperature out of the allowed range(must be between -10 and 50)')

    except ValueError as err:
        return str(err)

# Test the function
inputs = ["129", "12.9", "-15", "sun", "-10.1"]
for input_str in inputs:
    print(f"Temperature: {parse_temperature(input_str)}")
